/* ARGUS minimal terminal — a SELF-CONTAINED, interactive fallback used when the
 * full xterm.js is not vendored.  Unlike the old display-only stub, this one
 * CAPTURES KEYBOARD INPUT and feeds it to the onData() callback, so the human
 * can actually type into an Active Shell / RCE console with zero dependencies.
 *
 * For the richer real terminal (colours, resize, scrollback) you may still drop
 * the upstream build in over this file:
 *   curl -sL https://cdn.jsdelivr.net/npm/xterm@5.3.0/lib/xterm.min.js -o static/vendor/xterm.min.js
 *   curl -sL https://cdn.jsdelivr.net/npm/xterm@5.3.0/css/xterm.css   -o static/vendor/xterm.min.css
 */
(function () {
  if (window.Terminal && window.Terminal.__argus !== true) return; // real xterm present

  function clearNode(node) {
    if (!node) return;
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  function Terminal(opts) {
    this.opts = opts || {};
    this._container = null;
    this._out = null;
    this._onData = null;
    this._keyHandler = null;
    // Consumers (e.g. ShellManager's ResizeObserver) probe
    // _core._renderService._renderer._actualCell{Width,Height}; expose a benign
    // shape so they fall back to defaults instead of throwing a TypeError.
    this._core = { _renderService: { _renderer: { _actualCellWidth: 8, _actualCellHeight: 17 } } };
  }

  Terminal.prototype.open = function (el) {
    this._container = el;
    el.style.background = '#040608';
    el.style.color = '#e2e8f0';
    el.style.fontFamily = "'JetBrains Mono', 'Courier New', monospace";
    el.style.fontSize = '13px';
    el.style.padding = '8px';
    el.style.overflowY = 'auto';
    el.style.whiteSpace = 'pre-wrap';
    el.style.wordBreak = 'break-all';
    el.style.outline = 'none';
    el.style.cursor = 'text';
    // Make the terminal focusable so it can receive keyboard events.
    if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');

    this._out = document.createElement('div');
    el.appendChild(this._out);

    // Focus on click; subtle highlight when focused.
    el.addEventListener('mousedown', function () { setTimeout(function () { el.focus(); }, 0); });
    el.addEventListener('focus', function () { el.style.boxShadow = 'inset 0 0 0 1px rgba(0,212,255,0.4)'; });
    el.addEventListener('blur', function () { el.style.boxShadow = 'none'; });

    // Capture keystrokes → translate to terminal data → onData callback.
    // The backend (PTY or RCE console) echoes input back, so we do NOT echo
    // locally (avoids double characters).
    var self = this;
    this._keyHandler = function (e) {
      if (!self._onData) return;
      var data = null;
      if (e.key === 'Enter')          data = '\r';
      else if (e.key === 'Backspace') data = '\x7f';
      else if (e.key === 'Tab')       data = '\t';
      else if (e.key === 'Escape')    data = '\x1b';
      else if (e.key === 'ArrowUp')   data = '\x1b[A';
      else if (e.key === 'ArrowDown') data = '\x1b[B';
      else if (e.key === 'ArrowRight')data = '\x1b[C';
      else if (e.key === 'ArrowLeft') data = '\x1b[D';
      else if (e.ctrlKey && e.key && e.key.length === 1) {
        var c = e.key.toLowerCase().charCodeAt(0) - 96; // Ctrl-A..Z -> 1..26
        if (c >= 1 && c <= 26) data = String.fromCharCode(c);
      } else if (!e.altKey && !e.metaKey && e.key && e.key.length === 1) {
        data = e.key; // printable character
      }
      if (data !== null) {
        e.preventDefault();
        self._onData(data);
      }
    };
    el.addEventListener('keydown', this._keyHandler);

    // Allow paste → send the text through onData.
    el.addEventListener('paste', function (e) {
      if (!self._onData) return;
      e.preventDefault();
      var txt = (e.clipboardData || window.clipboardData).getData('text');
      if (txt) self._onData(txt.replace(/\r\n/g, '\r').replace(/\n/g, '\r'));
    });
  };

  Terminal.prototype.write = function (data) {
    if (!this._out) return;
    var clean = String(data).replace(/\x1b\[[0-9;]*[mGKHFABCDJr]/g, '').replace(/\r/g, '');
    this._out.textContent += clean;
    if (this._container) this._container.scrollTop = this._container.scrollHeight;
  };
  Terminal.prototype.writeln = function (data) { this.write(data + '\n'); };
  Terminal.prototype.clear = function () { if (this._out) this._out.textContent = ''; };
  Terminal.prototype.dispose = function () {
    if (this._container && this._keyHandler) {
      this._container.removeEventListener('keydown', this._keyHandler);
    }
    clearNode(this._container);
    this._out = null; this._onData = null;
  };
  Terminal.prototype.onData = function (cb) { this._onData = cb; };
  Terminal.prototype.focus = function () { if (this._container) this._container.focus(); };
  Terminal.prototype.resize = function () {};
  Terminal.prototype.reset = function () {};

  Terminal.__argus = true; // marker so a later real xterm load can replace us
  window.Terminal = Terminal;
  console.info('[ARGUS] interactive minimal terminal active (keyboard input enabled). '
    + 'Drop real xterm.js over static/vendor/xterm.min.js for the full terminal.');
})();
